function isSkippablePrefix(span: string): boolean {
  let at = 0;
  for (;;) {
    const quote = quoteMarkerLength(span, at);
    if (quote > 0) {
      at += quote;
      continue;
    }
    const list = listMarkerLength(span, at);
    if (list > 0) {
      at += list;
      continue;
    }
    while (isIndent(span.charCodeAt(at))) {
      at += 1;
    }
    return at === span.length;
  }
}
